void FAnimNode_CallFunction::CallFunctionFromCallSite(EAnimFunctionCallSite InCallSite, const FAnimationBaseContext& InContext) const
{
	if(CallSite == InCallSite)
	{
		GetFunction().Call(InContext.AnimInstanceProxy->GetAnimInstanceObject());
	}
}

void FAnimNode_CallFunction::Update_AnyThread(const FAnimationUpdateContext& InContext)
{
	CallFunctionFromCallSite(EAnimFunctionCallSite::OnUpdate, InContext);

	bool bBecameRelevant = false;
	if(!Counter.HasEverBeenUpdated() || !Counter.WasSynchronizedCounter(InContext.AnimInstanceProxy->GetUpdateCounter()))
	{
		bBecameRelevant = true;
		CurrentWeight = 0.0f;
		CallFunctionFromCallSite(EAnimFunctionCallSite::OnBecomeRelevant, InContext);
	}

	const float NewWeight = InContext.GetFinalBlendWeight();
	if(FAnimWeight::IsFullWeight(CurrentWeight) && !FAnimWeight::IsFullWeight(NewWeight))
	{
		CallFunctionFromCallSite(EAnimFunctionCallSite::OnStartedBlendingOut, InContext);
	}

	if(!FAnimWeight::IsRelevant(CurrentWeight) && FAnimWeight::IsRelevant(NewWeight))
	{
		CallFunctionFromCallSite(EAnimFunctionCallSite::OnStartedBlendingIn, InContext);
	}

	if(!FAnimWeight::IsFullWeight(CurrentWeight) && FAnimWeight::IsFullWeight(NewWeight))
	{
		CallFunctionFromCallSite(EAnimFunctionCallSite::OnFinishedBlendingIn, InContext);
	}

	Source.Update(InContext);

	if(bBecameRelevant)
	{
		CallFunctionFromCallSite(EAnimFunctionCallSite::OnBecomeRelevantPostRecursion, InContext);
	}

	CallFunctionFromCallSite(EAnimFunctionCallSite::OnUpdatePostRecursion, InContext);

	Counter.SynchronizeWith(InContext.AnimInstanceProxy->GetUpdateCounter());
	CurrentWeight = NewWeight;
}

fn refresh_grounded(&self, ctx: &NodeContext) -> Result<(), GraphError> {
    let scalar =
        |key, default| source_input_data(ctx, key).map_or(Ok(default), |value| value.as_f32());
    let boolean =
        |key, default| source_input_data(ctx, key).map_or(Ok(default), |value| value.as_bool());
    let vector =
        |key| source_input_data(ctx, key).map_or(Ok(Vec3::ZERO), |value| value.as_vec3());
    let rotation = source_input_data(ctx, "locomotion_state.rotation_quaternion_world_space")
        .map_or(Ok(Quat::IDENTITY), |value| value.as_quat())?;
    let velocity = vector("locomotion_state.velocity_world_space")?;
    let direction = crate::als::animation::velocity_blend_direction(velocity, rotation);
    let dt = scalar("animation.delta_seconds", 0.0)?;
    let alpha = |half_life: f32| {
        1.0 - crate::als::animation::inv_exp_approx(
            std::f32::consts::LN_2 / (half_life + 1e-8) * dt,
        )
    };
    let velocity_alpha = if boolean(
        "grounded_state.velocity_blend.b_initialization_required",
        true,
    )? {
        1.0
    } else {
        alpha(0.1)
    };
    set_source_property(
        ctx,
        "grounded_state.velocity_blend.b_initialization_required",
        false,
    )?;
    for (key, target) in [
        (
            "grounded_state.velocity_blend.forward_amount",
            (-direction.z).max(0.0),
        ),
        (
            "grounded_state.velocity_blend.backward_amount",
            direction.z.max(0.0),
        ),
        (
            "grounded_state.velocity_blend.left_amount",
            (-direction.x).max(0.0),
        ),
        (
            "grounded_state.velocity_blend.right_amount",
            direction.x.max(0.0),
        ),
    ] {
        set_source_property(ctx, key, scalar(key, 0.0)?.lerp(target, velocity_alpha))?;
    }
    let target_lean = crate::als::animation::acceleration_amount(
        vector("locomotion_state.acceleration_world_space")?,

pub fn set_source_property(
    ctx: &NodeContext,
    key: &str,
    value: impl Into<DataValue>,
) -> Result<(), GraphError> {
    let frame = ctx.graph_context.frame_index();
    let state = source_instance_properties(ctx)?;
    state.values.insert(key.to_owned(), value.into());
    state.write_frames.insert(key.to_owned(), frame);
    Ok(())
}

pub fn source_call_became_relevant(ctx: &NodeContext) -> Result<bool, GraphError> {
    let frame = ctx.graph_context.frame_index();
    let previous = source_instance_properties(ctx)?
        .call_frames
        .insert((ctx.graph_context.context_id, ctx.node_id), frame);
    Ok(previous.is_none_or(|previous| frame.wrapping_sub(previous) % u64::from(u16::MAX) > 1))
}

#[derive(Reflect, Clone, Debug)]
pub struct SourcePropertyAssignment {
    pub property: String,
    pub value: DataValue,
}

#[derive(Reflect, Clone, Debug, Default)]
#[reflect(Default, NodeLike)]
#[type_path = "als_ext"]
pub struct SourcePropertyWriteNode {
    pub assignments: Vec<SourcePropertyAssignment>,
    pub on_become_relevant: bool,
}

impl NodeLike for SourcePropertyWriteNode {
    fn update(&self, mut ctx: NodeContext) -> Result<(), GraphError> {
        let became_relevant = source_call_became_relevant(&ctx)?;
        if !self.on_become_relevant || became_relevant {
            for assignment in &self.assignments {
                set_source_property(&ctx, &assignment.property, assignment.value.clone())?;
            }
        }
        let pose = ctx.data_back("Source")?.into_pose()?;
        ctx.set_time(pose.timestamp);
        ctx.set_data_fwd("Pose", pose);
        *ctx.state_mut_or_else(AnimationContextState::default)? =
            pose_input_context_state(&ctx, "Source").unwrap_or_default();
        Ok(())
